// "Late Night Session" - an original lo-fi hip-hop instrumental for the Purphex Music showcase.
// Written and rendered entirely in code: FM electric piano, round bass, soft pads, swung hats and vinyl are synthesised here;
// the kick and the rim snare are Purphex library sounds (Purphex Sounds licence: generated by Purphex's own code, free for commercial music).
// csc LofiComposer.cs   run: LofiComposer.exe <out.wav> <bars> [seed]
using System; using System.IO; using System.Collections.Generic;

static class Lofi
{
    const int SR = 48000; const double BPM = 80; static double Beat { get { return 60.0 / BPM; } } static double Bar { get { return Beat * 4; } }
    static float[] L, R; static int N;
    static Random rnd;

    // ---------- helpers ----------
    static double Mtof(double m) { return 440.0 * Math.Pow(2, (m - 69) / 12.0); }
    static void Add(int i, double l, double r) { if (i >= 0 && i < N) { L[i] += (float)l; R[i] += (float)r; } }
    static float[][] ReadWav(string path)
    {
        var b = File.ReadAllBytes(path); int p = 12, ch = 2, rate = 44100, bits = 16, fmt = 1; int dataAt = -1, dataLen = 0;
        while (p + 8 <= b.Length) { string id = System.Text.Encoding.ASCII.GetString(b, p, 4); int len = BitConverter.ToInt32(b, p + 4);
            if (id == "fmt ") { fmt = BitConverter.ToInt16(b, p + 8); ch = BitConverter.ToInt16(b, p + 10); rate = BitConverter.ToInt32(b, p + 12); bits = BitConverter.ToInt16(b, p + 22); if (fmt == -2 && len >= 40) fmt = BitConverter.ToInt16(b, p + 32); }
            if (id == "data") { dataAt = p + 8; dataLen = Math.Min(len, b.Length - dataAt); break; } p += 8 + len + (len & 1); }
        int bps = bits / 8, frames = dataLen / (bps * ch); var src = new float[2][] { new float[frames], new float[frames] };
        for (int f = 0; f < frames; f++) for (int c = 0; c < 2; c++) { int cc = Math.Min(c, ch - 1); int o = dataAt + (f * ch + cc) * bps; double v;
            if (fmt == 3) v = BitConverter.ToSingle(b, o); else if (bits == 16) v = BitConverter.ToInt16(b, o) / 32768.0; else if (bits == 24) v = ((b[o] | (b[o + 1] << 8) | (b[o + 2] << 16)) << 8 >> 8) / 8388608.0; else v = BitConverter.ToInt32(b, o) / 2147483648.0; src[c][f] = (float)v; }
        if (rate == SR) return src; int outN = (int)((long)frames * SR / rate); var o2 = new float[2][] { new float[outN], new float[outN] };
        for (int i = 0; i < outN; i++) { double sp = i * (double)rate / SR; int a = (int)sp; double fr = sp - a; for (int c = 0; c < 2; c++) { float x0 = src[c][Math.Min(a, frames - 1)], x1 = src[c][Math.Min(a + 1, frames - 1)]; o2[c][i] = (float)(x0 + (x1 - x0) * fr); } }
        return o2;
    }
    // ---------- separate buses so each gets its own treatment ----------
    class Bus { public float[] L, R; public Bus(int n) { L = new float[n]; R = new float[n]; } public void Add(int i, double l, double r) { if (i >= 0 && i < L.Length) { L[i] += (float)l; R[i] += (float)r; } } }
    static Bus keys, bass, pad, drums, hats, vinyl, bells;

    // ---------- the electric piano (FM tine) ----------
    static void EP(Bus b, double t0, double midi, double vel, double dur, double pan)
    {
        double f = Mtof(midi); int s0 = (int)(t0 * SR); int len = (int)((dur + 2.2) * SR); double ph = 0, mph = 0, bph = 0; double bright = 0.6 + 0.8 * vel;
        double gl = Math.Cos((pan + 1) * Math.PI / 4), gr = Math.Sin((pan + 1) * Math.PI / 4);
        for (int i = 0; i < len; i++)
        {
            double t = i / (double)SR; double wow = 1 + 0.0016 * Math.Sin(2 * Math.PI * 0.55 * (t0 + t)) + 0.0006 * Math.Sin(2 * Math.PI * 3.1 * (t0 + t));
            double idx = bright * (1.6 * Math.Exp(-t * 4.0) + 0.35);
            mph += 2 * Math.PI * f * wow / SR; ph += 2 * Math.PI * f * wow / SR; bph += 2 * Math.PI * f * 7.02 / SR;
            double tone = Math.Sin(ph + idx * Math.Sin(mph)) + 0.14 * vel * Math.Sin(bph) * Math.Exp(-t * 14) + 0.06 * Math.Sin(2 * ph);
            double env = Math.Min(1, t / 0.004) * Math.Exp(-t / (1.6 + 0.8 * (60 / midi)));
            if (t > dur) env *= Math.Exp(-(t - dur) / 0.28);   // key released
            double v = tone * env * vel * 0.16; double trem = 1 + 0.18 * Math.Sin(2 * Math.PI * 4.4 * (t0 + t));
            b.Add(s0 + i, v * gl * trem, v * gr * (2 - trem));
        }
    }
    // ---------- a bell / music box for the melody ----------
    static void Bell(Bus b, double t0, double midi, double vel, double pan)
    {
        double f = Mtof(midi); int s0 = (int)(t0 * SR), len = (int)(2.5 * SR); double gl = Math.Cos((pan + 1) * Math.PI / 4), gr = Math.Sin((pan + 1) * Math.PI / 4);
        for (int i = 0; i < len; i++) { double t = i / (double)SR; double v = (Math.Sin(2 * Math.PI * f * t + 1.2 * Math.Exp(-t * 6) * Math.Sin(2 * Math.PI * f * 3.5 * t)) * Math.Exp(-t * 2.2) + 0.25 * Math.Sin(2 * Math.PI * f * 2 * t) * Math.Exp(-t * 4)) * Math.Min(1, t / 0.003) * vel * 0.09; b.Add(s0 + i, v * gl, v * gr); }
    }
    // ---------- round bass ----------
    static void Bass(double t0, double midi, double dur, double vel)
    {
        double f = Mtof(midi); int s0 = (int)(t0 * SR), len = (int)((dur + 0.15) * SR); double ph = 0;
        for (int i = 0; i < len; i++) { double t = i / (double)SR; ph += 2 * Math.PI * f / SR; double env = Math.Min(1, t / 0.012) * (0.75 + 0.25 * Math.Exp(-t * 3)); if (t > dur) env *= Math.Exp(-(t - dur) / 0.05);
            double x = Math.Sin(ph) + 0.22 * Math.Sin(2 * ph) + 0.05 * Math.Sin(3 * ph); x = Math.Tanh(x * 1.3) * env * vel * 0.30; bass.Add(s0 + i, x, x); }
    }
    // ---------- warm pad ----------
    static void Pad(double t0, double[] notes, double dur)
    {
        int s0 = (int)(t0 * SR), len = (int)((dur + 1.5) * SR); var lp = new double[2];
        foreach (double m in notes)
        {
            double f = Mtof(m); double[] ph = { rnd.NextDouble(), rnd.NextDouble(), rnd.NextDouble() }; double[] dt = { 0.997, 1.0, 1.0035 }; double zl = 0, zr = 0;
            for (int i = 0; i < len; i++) { double t = i / (double)SR; double env = Math.Min(1, t / 1.4) * (t > dur ? Math.Exp(-(t - dur) / 0.7) : 1); double sl = 0, sr = 0;
                for (int k = 0; k < 3; k++) { ph[k] += f * dt[k] / SR; ph[k] -= Math.Floor(ph[k]); double saw = 2 * ph[k] - 1; if (k == 0) sl += saw; else if (k == 2) sr += saw; else { sl += saw * 0.6; sr += saw * 0.6; } }
                zl += (sl - zl) * 0.045; zr += (sr - zr) * 0.045; pad.Add(s0 + i, zl * env * 0.020, zr * env * 0.020); }
        }
    }
    // ---------- drums ----------
    static float[][] kick, snare, snare2;
    static void Sample(Bus b, float[][] s, double t0, double vel, double pan)
    {
        int s0 = (int)(t0 * SR); double gl = Math.Cos((pan + 1) * Math.PI / 4) * 1.414, gr = Math.Sin((pan + 1) * Math.PI / 4) * 1.414;
        for (int i = 0; i < s[0].Length; i++) b.Add(s0 + i, s[0][i] * vel * gl, s[1][i] * vel * gr);
    }
    static void Hat(double t0, double vel, bool open, double pan)
    {
        int s0 = (int)(t0 * SR), len = (int)((open ? 0.35 : 0.06) * SR); double hp = 0, prev = 0, bp = 0; double gl = Math.Cos((pan + 1) * Math.PI / 4), gr = Math.Sin((pan + 1) * Math.PI / 4);
        for (int i = 0; i < len; i++) { double t = i / (double)SR; double n = rnd.NextDouble() * 2 - 1; hp = 0.92 * (hp + n - prev); prev = n; bp += (hp - bp) * 0.5;
            double env = Math.Exp(-t / (open ? 0.11 : 0.016)) * Math.Min(1, t / 0.0008); double v = bp * env * vel * 0.11; hats.Add(s0 + i, v * gl, v * gr); }
    }
    static void Shaker(double t0, double vel)
    {
        int s0 = (int)(t0 * SR), len = (int)(0.09 * SR); double hp = 0, prev = 0;
        for (int i = 0; i < len; i++) { double t = i / (double)SR; double n = rnd.NextDouble() * 2 - 1; hp = 0.85 * (hp + n - prev); prev = n; double env = Math.Sin(Math.PI * Math.Min(1, t / 0.09)) * Math.Exp(-t * 18); double v = hp * env * vel * 0.05; hats.Add(s0 + i, v * 0.7, v * 1.0); }
    }
    // ---------- effects ----------
    static void OnePoleLP(float[] x, double fc) { double a = 1 - Math.Exp(-2 * Math.PI * fc / SR), z = 0; for (int i = 0; i < x.Length; i++) { z += (x[i] - z) * a; x[i] = (float)z; } }
    static void OnePoleHP(float[] x, double fc) { double a = Math.Exp(-2 * Math.PI * fc / SR), y = 0, px = 0; for (int i = 0; i < x.Length; i++) { y = a * (y + x[i] - px); px = x[i]; x[i] = (float)y; } }
    static void Sat(float[] x, double drive) { double n = Math.Tanh(drive); for (int i = 0; i < x.Length; i++) x[i] = (float)(Math.Tanh(x[i] * drive) / n); }
    // a small Freeverb-style room
    static void Reverb(Bus src, Bus dst, double wet, double room, double damp)
    {
        int[] cl = { 1557, 1617, 1491, 1422, 1277, 1356, 1188, 1116 }; int[] al = { 556, 441, 341, 225 }; double sc = SR / 44100.0;
        for (int ch = 0; ch < 2; ch++)
        {
            var x = ch == 0 ? src.L : src.R; var y = new double[x.Length]; int spread = ch * 23;
            foreach (int c0 in cl) { int n = (int)((c0 + spread) * sc); var buf = new double[n]; int p = 0; double f = 0; for (int i = 0; i < x.Length; i++) { double o = buf[p]; f = o * (1 - damp) + f * damp; buf[p] = x[i] * 0.015 + f * room; p = (p + 1) % n; y[i] += o; } }
            foreach (int a0 in al) { int n = (int)((a0 + spread) * sc); var buf = new double[n]; int p = 0; for (int i = 0; i < y.Length; i++) { double b = buf[p]; double o = -y[i] + b; buf[p] = y[i] + b * 0.5; p = (p + 1) % n; y[i] = o; } }
            var d = ch == 0 ? dst.L : dst.R; for (int i = 0; i < d.Length; i++) d[i] += (float)(y[i] * wet);
        }
    }
    static void Mix(Bus b, double gain, double[] envGain = null) { for (int i = 0; i < N; i++) { double g = gain * (envGain == null ? 1 : envGain[i]); L[i] += (float)(b.L[i] * g); R[i] += (float)(b.R[i] * g); } }

    // ---------- the song ----------
    // progressions (bass root, then the piano voicing)
    static readonly double[][] ProgA = { new double[] { 43, 58, 62, 65, 69 }, new double[] { 48, 58, 62, 64, 69 }, new double[] { 41, 57, 60, 64, 67 }, new double[] { 38, 53, 57, 60, 64 } };   // Gm9  C13  Fmaj9  Dm9
    static readonly double[][] ProgB = { new double[] { 46, 57, 60, 62, 65 }, new double[] { 45, 55, 60, 64, 67 }, new double[] { 43, 58, 62, 65, 69 }, new double[] { 48, 58, 62, 65, 69 } };   // Bbmaj9  Am9  Gm9  C9sus
    // two short melodies (beat offset in the bar, midi note, length in beats); bar index inside the 4-bar phrase
    static readonly double[][] Mel1 = { new double[] { 0, 1.5, 77, 0.5 }, new double[] { 0, 2, 76, 1 }, new double[] { 0, 3.5, 74, 0.5 }, new double[] { 1, 0.5, 72, 1.5 }, new double[] { 1, 2.5, 74, 0.5 }, new double[] { 1, 3, 76, 1 },
        new double[] { 2, 1.5, 72, 0.5 }, new double[] { 2, 2, 69, 1.5 }, new double[] { 3, 0.5, 72, 0.5 }, new double[] { 3, 1, 74, 2 } };
    static readonly double[][] Mel2 = { new double[] { 0, 0.5, 81, 0.5 }, new double[] { 0, 1, 79, 0.5 }, new double[] { 0, 1.5, 77, 1.5 }, new double[] { 1, 1, 76, 0.5 }, new double[] { 1, 1.5, 72, 0.5 }, new double[] { 1, 2, 76, 1.5 },
        new double[] { 2, 0.5, 74, 0.5 }, new double[] { 2, 1, 72, 0.5 }, new double[] { 2, 1.5, 70, 1.5 }, new double[] { 3, 2, 72, 0.5 }, new double[] { 3, 2.5, 74, 0.5 }, new double[] { 3, 3, 77, 1 } };

    static double Swing(int step) { return step * Beat / 4 + (step % 2 == 1 ? Beat / 4 * 0.22 : 0); }   // 16ths with a lazy swing
    static double Hum() { return (rnd.NextDouble() - 0.5) * 0.012; }

    static int Main(string[] a)
    {
        string outp = a.Length > 0 ? a[0] : "late-night-session.wav"; int bars = a.Length > 1 ? int.Parse(a[1]) : 80; rnd = new Random(a.Length > 2 ? int.Parse(a[2]) : 7);
        string lib = Path.Combine(Environment.GetEnvironmentVariable("LOCALAPPDATA"), "YtToMp3", "sounds", "jazzy-lofi", "Drum One-Shots");
        kick = ReadWav(Path.Combine(lib, "Kick Deep 03.wav")); snare = ReadWav(Path.Combine(lib, "Snare Rim Crack 05.wav")); snare2 = ReadWav(Path.Combine(lib, "Snare Snap 02.wav"));
        double total = bars * Bar + 4.0; N = (int)(total * SR); L = new float[N]; R = new float[N];
        keys = new Bus(N); bass = new Bus(N); pad = new Bus(N); drums = new Bus(N); hats = new Bus(N); vinyl = new Bus(N); bells = new Bus(N);
        // the shape of the song (in bars): intro, groove, melody, breakdown, second groove, last melody, outro
        int intro = 4, outro = 6; int body = bars - intro - outro; int brk0 = intro + body / 2 - 4, brk1 = brk0 + 6;
        for (int b = 0; b < bars; b++)
        {
            double t = b * Bar; bool inIntro = b < intro, inOutro = b >= bars - outro, inBreak = b >= brk0 && b < brk1;
            bool useB = inBreak || (b >= brk1 && b < brk1 + 8) || (b >= intro + 16 && b < intro + 24);
            var ch = (useB ? ProgB : ProgA)[b % 4];
            // piano: the chord on beat 1 (strummed), and a softer push on the "and" of 3 now and then
            double vel = inIntro ? 0.55 : 0.75; for (int k = 1; k < ch.Length; k++) EP(keys, t + Hum() + (k - 1) * 0.018, ch[k], vel * (0.85 + 0.15 * rnd.NextDouble()), Bar * 0.62, -0.35 + 0.18 * k);
            if (!inIntro && b % 2 == 1) for (int k = 2; k < ch.Length; k++) EP(keys, t + Swing(10) + Hum() + (k - 2) * 0.012, ch[k], 0.42, Beat * 1.2, -0.2 + 0.12 * k);
            // pad on the chord tones, and the bass (not in the intro)
            if (!inOutro || b < bars - 2) Pad(t, new[] { ch[1], ch[2] + 12, ch[3] }, Bar);
            if (!inIntro && !inBreak && b < bars - 2)
            {
                double root = ch[0]; double next = (useB ? ProgB : ProgA)[(b + 1) % 4][0];
                Bass(t + 0.01, root, Beat * 1.6, 0.9); Bass(t + Swing(10), root + 7 > 50 ? root - 5 : root + 7, Beat * 0.7, 0.6); Bass(t + Swing(14), next + (next > root ? -1 : 1), Beat * 0.4, 0.55);
            }
            // drums
            bool drumsOn = !inIntro && !inBreak && b < bars - outro + 2;
            if (drumsOn)
            {
                Sample(drums, kick, t + Swing(0) + 0.004, 0.75, 0); Sample(drums, kick, t + Swing(7) + 0.006, 0.45, 0); if (b % 2 == 0) Sample(drums, kick, t + Swing(10), 0.6, 0);
                Sample(drums, snare, t + Swing(4) + 0.012, 0.5, 0.05); Sample(drums, snare, t + Swing(12) + 0.014, 0.52, 0.05); if (b % 4 == 3) Sample(drums, snare2, t + Swing(15) + 0.01, 0.16, 0.1);
                for (int s = 0; s < 16; s += 2) Hat(t + Swing(s) + Hum() * 0.5, (s % 4 == 0 ? 0.6 : 0.85) * (0.8 + 0.2 * rnd.NextDouble()), b % 4 == 3 && s == 14, 0.25);
                if (b >= intro + 8) for (int s = 1; s < 16; s += 4) Shaker(t + Swing(s + 2), 0.7);
            }
            if (inBreak && b >= brk0 + 2) for (int s = 0; s < 16; s += 4) Hat(t + Swing(s + 2), 0.35, false, 0.25);   // the breakdown keeps a quiet pulse
            // melodies: bells on the second phrase, piano melody later on
            int phraseBar = (b - intro) % 4;
            if (!inBreak && b >= intro + 8 && b < intro + 16) foreach (var m in Mel1) if ((int)m[0] == phraseBar) Bell(bells, t + Swing((int)(m[1] * 4)) + Hum(), m[2], 0.8, 0.35);
            if (b >= brk1 + 8 && b < bars - outro) foreach (var m in (b / 4 % 2 == 0 ? Mel1 : Mel2)) if ((int)m[0] == phraseBar) EP(keys, t + Swing((int)(m[1] * 4)) + Hum(), m[2] + 12, 0.5, m[3] * Beat, 0.3);
            if (inBreak) foreach (var m in Mel2) if ((int)m[0] == phraseBar) Bell(bells, t + Swing((int)(m[1] * 4)) + Hum(), m[2], 0.65, -0.3);
        }
        // the last chord rings out
        { double t = bars * Bar; var ch = ProgA[2]; for (int k = 1; k < ch.Length; k++) EP(keys, t + (k - 1) * 0.03, ch[k], 0.6, 2.5, -0.35 + 0.18 * k); }
        // vinyl: soft hiss and the odd crackle, all the way through
        { double z = 0; for (int i = 0; i < N; i++) { double n = rnd.NextDouble() * 2 - 1; z += (n - z) * 0.12; double v = z * 0.0035; if (rnd.NextDouble() < 0.00025) v += (rnd.NextDouble() - 0.5) * 0.06; vinyl.Add(i, v, v * 0.9 + (rnd.NextDouble() - 0.5) * 0.0005); } OnePoleLP(vinyl.L, 5000); OnePoleLP(vinyl.R, 5000); }
        // bus treatment
        foreach (var x in new[] { keys.L, keys.R }) { OnePoleLP(x, 3600); OnePoleLP(x, 5200); Sat(x, 1.4); }
        foreach (var x in new[] { bells.L, bells.R }) { OnePoleLP(x, 4200); }
        foreach (var x in new[] { bass.L, bass.R }) { OnePoleLP(x, 420); OnePoleLP(x, 700); OnePoleHP(x, 30); }
        foreach (var x in new[] { drums.L, drums.R }) { OnePoleLP(x, 6500); Sat(x, 1.8); OnePoleHP(x, 28); }
        foreach (var x in new[] { hats.L, hats.R }) { OnePoleLP(x, 7000); }
        foreach (var x in new[] { pad.L, pad.R }) { OnePoleHP(x, 120); }
        var verb = new Bus(N); var send = new Bus(N);
        for (int i = 0; i < N; i++) { send.L[i] = keys.L[i] * 0.55f + bells.L[i] * 0.8f + pad.L[i] * 0.5f + drums.L[i] * 0.12f; send.R[i] = keys.R[i] * 0.55f + bells.R[i] * 0.8f + pad.R[i] * 0.5f + drums.R[i] * 0.12f; }
        Reverb(send, verb, 0.9, 0.84, 0.45);
        // the intro opens up: a filter sweep on the keys over the first bars
        var introEnv = new double[N]; for (int i = 0; i < N; i++) { double t = i / (double)SR; introEnv[i] = 1; }
        Mix(keys, 1.0); Mix(bells, 1.0); Mix(bass, 1.0); Mix(pad, 1.0); Mix(drums, 0.9); Mix(hats, 0.8); Mix(vinyl, 1.0); Mix(verb, 0.55);
        { double z1 = 0, z2 = 0; double introLen = 4 * Bar; for (int i = 0; i < N; i++) { double t = i / (double)SR; if (t > introLen + 0.5) break; double fc = 600 + (16000 - 600) * Math.Pow(Math.Min(1, t / introLen), 2.2); double a1 = 1 - Math.Exp(-2 * Math.PI * fc / SR); z1 += (L[i] - z1) * a1; z2 += (R[i] - z2) * a1; double w = Math.Min(1, t / introLen); L[i] = (float)(z1 * (1 - w) + L[i] * w); R[i] = (float)(z2 * (1 - w) + R[i] * w); } }
        // gentle glue: slow RMS compressor, then a soft limiter
        { double env = 0; for (int i = 0; i < N; i++) { double lv = Math.Max(Math.Abs(L[i]), Math.Abs(R[i])); env += (lv * lv - env) * (lv * lv > env ? 0.002 : 0.00005); double rms = Math.Sqrt(env); double g = rms > 0.18 ? Math.Pow(0.18 / rms, 0.35) : 1; L[i] = (float)(L[i] * g); R[i] = (float)(R[i] * g); } }
        double peak = 0; for (int i = 0; i < N; i++) peak = Math.Max(peak, Math.Max(Math.Abs(L[i]), Math.Abs(R[i]))); double norm = 0.89 / Math.Max(1e-6, peak);
        for (int i = 0; i < N; i++) { L[i] = (float)Math.Tanh(L[i] * norm * 1.05) * 0.95f; R[i] = (float)Math.Tanh(R[i] * norm * 1.05) * 0.95f; }
        // a fade over the last bars
        { int fl = (int)(5.0 * SR); for (int i = 0; i < fl; i++) { double g = Math.Cos(i / (double)fl * Math.PI / 2); int j = N - fl + i; L[j] *= (float)g; R[j] *= (float)g; } }
        // write 24-bit 48 kHz stereo
        using (var w = new BinaryWriter(File.Create(outp)))
        {
            int dataLen = N * 2 * 3; w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF")); w.Write(36 + dataLen); w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt ")); w.Write(16); w.Write((short)1); w.Write((short)2); w.Write(SR); w.Write(SR * 6); w.Write((short)6); w.Write((short)24);
            w.Write(System.Text.Encoding.ASCII.GetBytes("data")); w.Write(dataLen);
            for (int i = 0; i < N; i++) foreach (float v in new[] { L[i], R[i] }) { int s = (int)Math.Round(Math.Max(-1, Math.Min(1, v)) * 8388607); w.Write((byte)(s & 255)); w.Write((byte)((s >> 8) & 255)); w.Write((byte)((s >> 16) & 255)); }
        }
        Console.WriteLine("wrote " + outp + " " + bars + " bars, " + total.ToString("0.0") + " s"); return 0;
    }
}
